package tn.esprit.partnerintelligence.service;import org.springframework.stereotype.Service;import tn.esprit.partnerintelligence.dto.PartnerIntelligenceOverviewDto;import tn.esprit.partnerintelligence.entity.*;import tn.esprit.partnerintelligence.repository.*;@Service public class InferenceOrchestratorService{ private final HealthScoringService hs; private final RecommendationEngineService rs; private final ForecastService fs; private final AnomalyDetectionService as; private final SummaryGenerationService ss; private final DealHealthScoreSnapshotRepository hRepo; private final RecommendationItemRepository rRepo; private final ForecastSnapshotRepository fRepo; private final AnomalyAlertRepository aRepo; private final PartnerInsightSummaryRepository sRepo; public InferenceOrchestratorService(HealthScoringService hs,RecommendationEngineService rs,ForecastService fs,AnomalyDetectionService as,SummaryGenerationService ss,DealHealthScoreSnapshotRepository hRepo,RecommendationItemRepository rRepo,ForecastSnapshotRepository fRepo,AnomalyAlertRepository aRepo,PartnerInsightSummaryRepository sRepo){this.hs=hs;this.rs=rs;this.fs=fs;this.as=as;this.ss=ss;this.hRepo=hRepo;this.rRepo=rRepo;this.fRepo=fRepo;this.aRepo=aRepo;this.sRepo=sRepo;} public PartnerIntelligenceOverviewDto run(Long p){ DealHealthScoreSnapshot h=new DealHealthScoreSnapshot(); h.setPartnerId(p); h.setDealId(1L); h.setHealthScore(hs.score(p,1L)); h.setConfidence(hs.confidence()); h.setFactors(hs.factors()); hRepo.save(h); RecommendationItem rec=rs.build(p,h.getHealthScore()); rRepo.save(rec); ForecastSnapshot f=new ForecastSnapshot(); f.setPartnerId(p); f.setHorizon("30d"); f.setPredictedRevenue(fs.forecast(p,"30d")); f.setConfidence(0.77); fRepo.save(f); if(as.detect(p)){ AnomalyAlert a=new AnomalyAlert(); a.setPartnerId(p); a.setAnomalyType("CONVERSION_DROP"); a.setExplanation(as.reason()); a.setSeverityScore(0.74); aRepo.save(a);} PartnerInsightSummary s=new PartnerInsightSummary(); s.setPartnerId(p); s.setSummary(ss.weeklySummary(p)); sRepo.save(s); return new PartnerIntelligenceOverviewDto(h.getHealthScore(),aRepo.findByStatus("OPEN").size(),rRepo.findByPartnerId(p).size(),f.getPredictedRevenue()); }}